import { useState } from "react";
import "./Title.css";

function Title({ sortName, sortNum, status }) {
  // function sortByText(text) {}

  return (
    <div className="mainTitle">
      <p className="titleP">Image</p>
      <div className="name" onClick={() => sortName("name")}>
        <p className="titleP">Name</p>
{status.name ? <svg
          xmlns="http://www.w3.org/2000/svg"
          height="24px"
          viewBox="0 -960 960 960"
          width="24px"
          fill="#e8eaed"
        >
          <path d="M440-800v487L216-537l-56 57 320 320 320-320-56-57-224 224v-487h-80Z" />
        </svg>
        :
        null}

      </div>
      <p className="titleP" onClick={() => sortName("surname")}>
        Surname
      </p>
      <p className="titleP" onClick={()=> sortNum('age')}>Age</p>
      <p className="titleP">Gender</p>
      <p className="titleP">Profession</p>
    </div>
  );
}

export default Title;
